 ["Desert Recipe"]={
  ["Look for information about cooking Sandworm Meat at the Twilight's Hammer camp west of Cenarion Hold."]={0,2678069672},
 },
 ["毁灭摩弗拉斯"]={
  ["从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。"]={0,863505440},
 },
 ["蛮鬃图腾"]={
  ["收集8颗草原狼前锋的牙齿，把它们交给血蹄村的穆尔·雷角。"]={32,2051302640},
 },
 ["古拉巴什、邪枝和枯木硬币"]={
  [""]={0,1362926344},
 },
 ["召唤"]={
  ["Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.\n\nYou have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.\n\nAssemble an army for this task, "..N.."!"]={0,1680193976},
 },
 ["刃叶的药剂"]={
  ["给在多兰纳尔的塞拉尔·刃叶带去6瓶狮王之力药剂和2瓶初级防御药剂。"]={0,507521464},
 },
 ["异种蝎的崛起"]={
  ["把报告带给奥格瑞玛的基尔兹宾·鼓眼。"]={178,1315774514},
  ["把报告带给达纳苏斯的格拉希娜·灵风。"]={77,1143887901},
  ["把拉斯卡尔的报告交给达纳苏斯的格拉希娜·灵风。"]={77,2713603629},
 },
 ["饥肠辘辘的基特斯"]={
  ["和厨师格鲁奥谈一谈。"]={77,2194975949},
 },
 ["进攻高塔"]={
  ["找到特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙，把它们交给避难谷地的斯奎尔图。"]={77,1216165629},
 },
 ["上古圣马之魂"]={
  ["Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it."]={5,11025789},
 },
 ["塞拉摩间谍"]={
  ["杀掉9个塞拉摩间谍，然后回到蕨墙村去见纳泽尔·血矛。"]={178,2246518330},
 },
 ["米奈希尔的礼物"]={
  ["到斯坦索姆城里去找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。"]={0,2669386408},
  ["把禁锢灵魂的遗物交给东瘟疫之地的莱尼德·巴萨罗梅。"]={0,3533915440},
 },
 ["杂味炖肉"]={
  ["弗娜·法布隆要求你将她的杂味炖肉食谱交给萨尔玛·萨丁。"]={77,1647942109},
  ["萨尔玛·萨丁需要3块秃鹫肉条、3只血牙野猪的头、3颗鱼人的眼睛和3棵秋葵。"]={77,131176245},
 },
 ["驾驶员的复仇"]={
  ["Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot."]={77,2178626501},
 },
 ["给赫布瑞姆的样本"]={
  ["把一箱蜘蛛毒带给贫瘠之地的药剂师赫布瑞姆。"]={178,2123770314},
 },
 ["迅猛龙角"]={
  ["从赤鳞镰爪龙身上收集5根完整的迅猛龙角，把它们交给棘齿城的米希瑞克斯。"]={0,2813990592},
 },
 ["希尔斯布莱德之战"]={
  ["杀掉6个希尔斯布莱德雇农和6个希尔斯布莱德农夫，还有农夫雷恩和农夫盖兹，然后返回塔伦米尔向达萨利亚报告。"]={178,1062068898},
  ["杀死15个希尔斯布莱德农民，然后回到塔伦米尔向达萨利亚汇报。"]={178,3154992778},
  ["Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.\n\nRetrieve a shipment of iron and report back to Darthalia in Tarren Mill."]={178,1269184218},
  ["杀掉波恩塞德镇长和4个希尔斯布莱德议员，摧毁《希尔斯布莱德宣言》，偷取希尔斯布莱德城镇文档，然后回到塔伦米尔向达萨利亚汇报。"]={178,1215733186},
  ["杀死工头邦德斯和10个希尔斯布莱德矿工，然后回到塔伦米尔向达萨利亚汇报。"]={178,2261623074},
  ["到丹加洛克去杀掉8个巡山人、4个火枪手、2个牧师，还有达伦·铁山上尉，然后回到塔伦米尔向达萨利亚汇报。"]={178,405676786},
  ["把达萨利亚的奖状交给幽暗城的布拉贡·血拳。"]={0,830836160},
 },
 ["Trouble in the Deeps"]={
  ["Speak to Je'neu Sancrea in Ashenvale."]={178,2044731818},
 },
 ["哨塔和碉堡"]={
  ["占领敌方的某座哨塔，然后向霜狼村的提卡·血牙复命。"]={178,911585562},
  ["摧毁敌方的某座哨塔或者碉堡中的旗帜，然后向丹巴达尔的杜尔根·雷矛复命。"]={77,1104017669},
 },
 ["拉尔德的午餐"]={
  ["Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.\n\nLard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls."]={178,2759979762},
 },
 ["大地的震颤"]={
  ["Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.\n\nPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.\n\nSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek."]={77,1573277861},
  ["帮加瑞克取回大地印章。"]={77,986949149},
 },
 ["马克里尔的月光酒"]={
  ["把马克里尔的月光酒交给南海镇的布鲁米·比格尔。"]={0,757906160},
 },
 ["长明的灯塔"]={
  ["给西部荒野灯塔中的葛瑞森船长带回5瓶灯油。"]={77,2615481013},
 },
 ["找到OOX-09/HL！"]={
  ["把定位器带到奥格索普的母体机器人那里去。$B$B奥格索普的母体机器人位于辛特兰的河水源头，就在隐匿石的附近。"]={0,2790670472},
 },
 ["树林蜘蛛的卵"]={
  ["给奥达希尔的基尔莎兰带回1枚树林蜘蛛的卵。"]={0,2950192384},
 },
 ["该死的手指头！"]={
  ["Hansel Heavyhands wants you to kill 20 Heavy War Golems.\n\nThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge."]={0,2966617944},
 },
 ["鳄鱼小子和有胡子的鱼人"]={
  [""]={0,2970466056},
 },
 ["送往暴风城的货物"]={
  ["把威廉的货物交给暴风城贸易区的摩根·匹斯特。"]={77,2334950117},
 },
 ["The Argent Hold"]={
  ["Open the Argent Hold and claim your reward."]={0,3187559352},
 },
 ["实验场"]={
  ["到主基地东南边的蛮爪洞穴中去找到霜狼军旗，然后把它交给拉格隆德。"]={0,839408744},
  ["到主基地东南边的冰翼洞穴中去找到雷矛军旗，然后把它交给哈格丁中尉。"]={0,2862657320},
 },
 ["萨特之角"]={
  ["为碎木哨岗的皮克希尔收集16只萨特的角。"]={178,3260470066},
 },
 ["远古石叶"]={
  ["Find the owner of the Ancient Petrified Leaf. Good luck, <name>; It's a big world."]={0,1592412096},
 },
 ["深入疯狂之口"]={
  ["Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.\n\nDo not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.\n\nAnd <name>, remember the Commander's words: \"Do what you must...\""]={0,3982357880},
 },
 ["重铸秩序"]={
  ["Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.\n\nKeep your wits about you, <name>. The Horde will defend the ranger lord with their very lives."]={0,2813496221},
 }
}

