function GetEntityLocations(entity)
    local locations = {}
    local mapIds = {}
    for sourceType, sources in pairs(entity) do
        if sourceType == "drop" then
            for sourceName, b in pairs(sources) do
                local locationMeta, ids = GetMonsterLocations(sourceName)
                if next(locationMeta) then
                    if locations[sourceType] == nil then locations[sourceType] = {} end
                    locations[sourceType][sourceName] = locationMeta
                    for c, zs in pairs(ids) do if mapIds[c] == nil then mapIds[c] = {} end for z, b in pairs(zs) do mapIds[c][z] = true end end
                end
            end
        end
        if sourceType == "rewardedby" then
            for sourceName, b in pairs(sources) do
                local locationMeta, ids = GetMonsterLocations(sourceName)
                if next(locationMeta) then
                    if locations[sourceType] == nil then locations[sourceType] = {} end
                    locations[sourceType][sourceName] = locationMeta
                    for c, zs in pairs(ids) do if mapIds[c] == nil then mapIds[c] = {} end for z, b in pairs(zs) do mapIds[c][z] = true end end
                end
            end
        end
        if sourceType == "contained" then
            for sourceName, b in pairs(sources) do
                local locationMeta, ids = GetObjectLocations(sourceName)
                if next(locationMeta) then
                    if locations[sourceType] == nil then locations[sourceType] = {} end
                    locations[sourceType][sourceName] = locationMeta
                    for c, zs in pairs(ids) do if mapIds[c] == nil then mapIds[c] = {} end for z, b in pairs(zs) do mapIds[c][z] = true end end
                end
            end
        end
        if sourceType == "contained_id" then
            for sourceId, b in pairs(sources) do
                local locationMeta, ids = GetNewObjectLocations(sourceId)
                if next(locationMeta) then
                    if locations[sourceType] == nil then locations[sourceType] = {} end
                    local sourceName = locationMeta.name
                    locationMeta.name = nil
                    locations[sourceType][sourceName] = locationMeta
                    for c, zs in pairs(ids) do if mapIds[c] == nil then mapIds[c] = {} end for z, b in pairs(zs) do mapIds[c][z] = true end end
                end
            end
        end
        if sourceType == "containedi" then
            for sourceName, b in pairs(sources) do
                local locationMeta, ids = GetItemLocations(sourceName)
                if next(locationMeta) then
                    if locations[sourceType] == nil then locations[sourceType] = {} end
                    locations[sourceType][sourceName] = locationMeta
                    for c, zs in pairs(ids) do if mapIds[c] == nil then mapIds[c] = {} end for z, b in pairs(zs) do mapIds[c][z] = true end end
                end
            end
        end
        if sourceType == "created" then
            for sourceName, b in pairs(sources) do
                local locationMeta, ids = GetItemLocations(sourceName)
                if next(locationMeta) then
                    if locations[sourceType] == nil then locations[sourceType] = {} end
                    locations[sourceType][sourceName] = locationMeta
                    for c, zs in pairs(ids) do if mapIds[c] == nil then mapIds[c] = {} end for z, b in pairs(zs) do mapIds[c][z] = true end end
                end
            end
        end
        if sourceType == "transforms" then
            for sourceName, b in pairs(sources) do
                local locationMeta, ids = GetMonsterLocations(sourceName)
                if next(locationMeta) then
                    if locations[sourceType] == nil then locations[sourceType] = {} end
                    locations[sourceType][sourceName] = locationMeta
                    for c, zs in pairs(ids) do if mapIds[c] == nil then mapIds[c] = {} end for z, b in pairs(zs) do mapIds[c][z] = true end end
                end
            end
        end
        if sourceType == "transformedby" then
            for sourceName, b in pairs(sources) do
                local locationMeta, ids = GetItemLocations(sourceName)
                if next(locationMeta) then
                    if locations[sourceType] == nil then locations[sourceType] = {} end
                    locations[sourceType][sourceName] = locationMeta
                    for c, zs in pairs(ids) do if mapIds[c] == nil then mapIds[c] = {} end for z, b in pairs(zs) do mapIds[c][z] = true end end
                end
            end
        end
        if sourceType == "openedby" then
            for sourceName, b in pairs(sources) do
                local locationMeta, ids = GetItemLocations(sourceName)
                if next(locationMeta) then
                    if locations[sourceType] == nil then locations[sourceType] = {} end
                    locations[sourceType][sourceName] = locationMeta
                    --for c, zs in pairs(ids) do if mapIds[c] == nil then mapIds[c] = {} end for z, b in pairs(zs) do mapIds[c][z] = true end end
                end
            end
        end
        if sourceType == "locations" then
            local added = false
            local class = UnitClass("Player")
            local race = UnitRace("Player")
            for i, location in pairs(sources) do
                if (not entity['locations_rr']) or (not entity['locations_rr'][i]) or QuestieCheckRequirements(class, race, nil, entity['locations_rr'][i]) then
                    local reformattedLocation = MapRegistry:ResolveLocationTuple(location)

                    if reformattedLocation then
                        if locations[sourceType] == nil then locations[sourceType] = {} end
                        table.insert(locations[sourceType], reformattedLocation)
                        if added == false then
                            local c, z = reformattedLocation[1], reformattedLocation[2]
                            if mapIds[c] == nil then mapIds[c] = {} end
                            mapIds[c][z] = true
                            added = true
                        end
                    else
                        --sources[i] = nil
                    end
                end
            end
        end
        if sourceType == "name" then
            locations[sourceType] = sources
        end
    end
    return locations, mapIds
end

function GetMonsterLocations(monsterName)
    -- Use ID-based lookup
    local unitId = QuestieUnitIds and QuestieUnitIds[monsterName]
    if unitId and QuestieUnitData and QuestieUnitData[unitId] then
        return GetEntityLocations(QuestieUnitData[unitId])
    end
    return {}, {}
end

function GetObjectLocations(objectName)
    -- Use ID-based lookup
    local objectId = QuestieObjectIds and QuestieObjectIds[objectName]
    if objectId and QuestieObjectData and QuestieObjectData[objectId] then
        return GetEntityLocations(QuestieObjectData[objectId])
    end
    return {}, {}
end

function GetNewObjectLocations(objectId)
    if QuestieNewObjects and QuestieNewObjects[objectId] then
        return GetEntityLocations(QuestieNewObjects[objectId])
    end
    return {}, {}
end

function GetItemLocations(itemName)
    -- Use ID-based lookup
    local itemId = QuestieItemIds and QuestieItemIds[itemName]
    if itemId and QuestieItemData and QuestieItemData[itemId] then
        -- Build item locations from drop sources
        local itemData = QuestieItemData[itemId]
        local allLocations = {}
        
        -- Get locations from drop units
        if itemData.dropUnits then
            for _, unitId in ipairs(itemData.dropUnits) do
                if QuestieUnitData and QuestieUnitData[unitId] and QuestieUnitData[unitId].locations then
                    for _, loc in ipairs(QuestieUnitData[unitId].locations) do
                        table.insert(allLocations, loc)
                    end
                end
            end
        end
        
        -- Get locations from contained objects
        if itemData.containedObjects then
            for _, objId in ipairs(itemData.containedObjects) do
                if QuestieObjectData and QuestieObjectData[objId] and QuestieObjectData[objId].locations then
                    for _, loc in ipairs(QuestieObjectData[objId].locations) do
                        table.insert(allLocations, loc)
                    end
                end
            end
        end
        
        if table.getn(allLocations) > 0 then
            return GetEntityLocations({ ["locations"] = allLocations, ["locationCount"] = table.getn(allLocations) })
        end
    end
    return {}, {}
end

function GetEventLocations(eventName)
    -- Events are now part of quest data - return empty for now
    return {}, {}
end

function GetReputationLocations(reputationName)
    if QuestieReputationsByName and QuestieReputationsByName[reputationName] then
        return GetEntityLocations(QuestieReputationsByName[reputationName])
    end
    return {}, {}
end

QuestieZoneLevelMap = {
}

function addQuestToZoneLevelMap(c, z, questHash, questInfo, locationMeta, questId)
    local level = questInfo['level']
    local variantLocationMeta = locationMeta
    variantLocationMeta['questName'] = questInfo['name']
    if QuestieZoneLevelMap[c] == nil then
        QuestieZoneLevelMap[c] = {};
    end
    if QuestieZoneLevelMap[c][z] == nil then
        QuestieZoneLevelMap[c][z] = {};
    end
    if QuestieZoneLevelMap[c][z][level] == nil then
        QuestieZoneLevelMap[c][z][level] = {};
    end
    if QuestieZoneLevelMap[c][z][level][questHash] == nil then
        QuestieZoneLevelMap[c][z][level][questHash] = { ["variants"] = {} }
    end
    QuestieZoneLevelMap[c][z][level][questHash]["variants"][questId or questInfo.questId or 0] = variantLocationMeta
end

